{
  "claims": [
    {
      "claim": "Per la naturalizzazione ordinaria in Svizzera, i requisiti di residenza variano a seconda del cantone e del comune, poiché la Confederazione stabilisce solo un quadro generale mentre i cantoni e i comuni possono avere requisiti più specifici.",
      "verdict": "supported"
    },
    {
      "claim": "Secondo le linee guida federali e la prassi comune, in totale sono richiesti 10 anni di residenza legale in Svizzera (compresi i periodi di residenza con permessi validi) prima di poter presentare domanda di naturalizzazione.",
      "verdict": "supported"
    },
    {
      "claim": "Di questi 10 anni, almeno 3 anni negli ultimi 5 anni immediatamente precedenti la domanda devono essere stati trascorsi in modo continuo.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Gli anni trascorsi in Svizzera tra l'8° e il 18° anno di età contano doppio (ossia vengono conteggiati come 2 anni per ogni anno effettivamente vissuto) nel calcolo totale dei 10 anni di residenza richiesti.",
      "verdict": "supported"
    },
    {
      "claim": "Tutti i periodi di residenza legale in Svizzera con permessi validi (come permesso B, C, permesso di dimora, ecc.) vengono calcolati integralmente per il requisito dei 10 anni.",
      "verdict": "supported"
    },
    {
      "claim": "Non vengono conteggiati i periodi di soggiorno illegali o con permessi scaduti.",
      "verdict": "supported"
    },
    {
      "claim": "I periodi trascorsi in Svizzera in qualità di studente, turista o con permessi temporanei non sempre soddisfano i requisiti di residenza per la naturalizzazione; in genere è richiesto un permesso di dimora o di domicilio valido.",
      "verdict": "supported"
    }
  ],
  "behavior_violation": false,
